# Auto-generated by sim/scripts/gen_mk_files.sh
# Starter regression test list regenerated from i3c/verify/tb/tests
# Format:
# BURST_LIMITS light=50 medium=20 heavy=10 extra=1
# BURST_PLAN light=seed-major medium=seed-major heavy=seed-major extra=seed-major
# Supported burst plan values: seed-major, packed, test-major
#   seed-major = finish all selected tests for one seed before the next seed
#   packed     = planner may group multiple tests/seeds in one burst for throughput
#   test-major = finish one test across its seed chunks before the next test
# Regression group format:
#   <label> : <level> <on/off> {
#   test_name
#   test_name | case_id | +PLUSARG=value [+FLAG]
# }
# label must be unique. level accepts light, medium/med, heavy/high, extra.
# off groups are skipped by --all and level selection.
# Prefix an individual test with # to disable it without auto-rediscovery.
# Metadata comments are parsed; other comment lines are ignored.
# Per-test compile requirement syntax is TEST_REQUIRES_COMPILE followed by
# <test_name>=<requirement>[,<requirement>...].
# Requirements are simulator-neutral; the runner maps them to backend options.
# TEST_REQUIRES_COMPILE i3c_ibi_target_tx_overflow_test=hdl_access

i3c_smoke : light on {
i3c_csr_smoke_test
i3c_sanity_test
}

i3c_ral : heavy on {
i3c_ral_all_regs_test
}

