# Separate DUT-Controller/two-UVM-Target scenario; it is not an alias of the
# DUT-Target test.
i3c_ibi_legacy_aliases : light on {
i3c_ibi_controller_rx_multi_target_test
}

# Work in progress. Tests that produce a functional IBI event receive
# +IBI_REQUIRE_COV from the generated plan. Reset-flush and invalid-target
# negative scenarios are explicit coverage-sample exceptions because their
# legal PASS path may intentionally produce no accepted IBI event.
# These tests are specification-facing and
# should PASS on a conforming DUT, but have not yet completed a clean simulation
# run. The pending-read test follows the advertised HCI Auto-Command capability
# and always completes the required Private Read contract.
i3c_ibi_wip : light on {
i3c_ibi_controller_rx_reset_flush_test
i3c_ibi_target_tx_recovery_cleanup_test
i3c_ibi_controller_rx_recovery_cleanup_test
i3c_ibi_controller_rx_mdb_decode_test
i3c_ibi_controller_rx_pending_read_notification_test
# Overflow closure uses separate test identities so regression and coverage
# results cannot accidentally close the opposite DUT role.
i3c_ibi_target_tx_overflow_test
i3c_ibi_controller_rx_overflow_test
}

# Coverage-directed random scenarios. The generated testplan assigns multiple
# default seeds and the random-seed tag only to this group; directed tests
# remain at seed 1. Explicit --seeds overrides every selected entry, while
# --rand-num only replaces seeds for this tagged group. Controller random runs
# one IBI per seed due the current Controller re-entry defect.
i3c_ibi_random : medium on {
i3c_ibi_target_tx_random_test | closure_24 | +IBI_RANDOM_ITERS=24 +IBI_RANDOM_MUST_HIT=1
i3c_ibi_target_tx_stress_test | ack_burst_100 | +IBI_RANDOM_ITERS=100 +IBI_STRESS_PROFILE=ack_burst
i3c_ibi_target_tx_stress_test | mixed_response_60 | +IBI_RANDOM_ITERS=60 +IBI_STRESS_PROFILE=mixed_response +IBI_RANDOM_MUST_HIT=1
i3c_ibi_controller_rx_random_test | policy_seed_sweep
}

