# RTL does not implement the HCI SOFT_RST self-clear behavior. Keep this
# and the positive no-MDB Controller reproduction out of ordinary regression
# selection until their RTL/design contracts are resolved.
i3c_ibi_rtl_unsupported : heavy off {
i3c_ibi_controller_rx_soft_rst_selfclear_test
i3c_ibi_controller_rx_no_mdb_test
}

# Contract-backed Target runtime eligibility negatives: no valid Dynamic
# Address and IBI_EN clear. This supported test is part of ordinary regression.
i3c_ibi_runtime_negative : heavy on {
i3c_ibi_target_tx_invalid_target_test
}

# Focused risk cases validated on the reviewed native RTL revision. FIFO IRQ and DAT
# no-match pass their scoreboards and SVA; multi-target recovery passes after
# controller-pad role selection and passive recovery-checker construction.
i3c_ibi_validated_rechecks : heavy on {
i3c_ibi_controller_rx_fifo_irq_test
i3c_ibi_controller_rx_policy_test | policy_dat_no_match | +IBI_POLICY_CASE=4
i3c_ibi_multi_target_recovery_test | | +IBI_REQUIRE_COV +IBI_DUT_CONTROLLER=1
}
